package com.trampolim.api.trust;
import java.util.*;import com.trampolim.api.radar.RadarBridge;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
/** Durable local request, idempotent remote delivery, and erasure tombstones; no shared session. */
public class ListingReportGateway {
 private final JdbcTemplate db;private final TransactionTemplate tx;private final RadarBridge bridge;private final String users,trail;
 public record Input(String reason,String details,boolean consent){}
 public ListingReportGateway(JdbcTemplate db,PlatformTransactionManager manager,RadarBridge bridge,boolean student){this.db=db;tx=new TransactionTemplate(manager);this.bridge=bridge;users=student?"student_users":"app_users";trail=student?"CAPACITA":"OPORTUNIDADES";}
 private long user(String email,boolean lock){String active=users.equals("app_users")?"account_type='PERSON'":"account_status='ACTIVE'";return db.queryForList("SELECT id FROM "+users+" WHERE LOWER(email)=LOWER(?) AND email_verified=TRUE AND "+active+(lock?" FOR UPDATE":""),Long.class,email).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN));}
 public Map<String,Object> submit(String email,long listing,Input p){if(listing<1||p==null||!p.consent()||!Set.of("PAYMENT_REQUEST","IDENTITY_MISUSE","MISLEADING","DUPLICATE","OTHER").contains(Objects.toString(p.reason(),"")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Selecione motivo e autorize o envio do relato à moderação, sem dados sensíveis.");String text=p.details()==null?"":p.details().trim();if(text.length()>1000||text.indexOf(0)>=0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Use até mil caracteres.");UUID receipt=tx.execute(status->{long uid=user(email,true);var old=db.queryForList("SELECT receipt,reason,details,state FROM listing_trust_reports WHERE user_id=? AND listing_id=?",uid,listing);if(!old.isEmpty()){var r=old.getFirst();if(!r.get("reason").equals(p.reason())||!r.get("details").equals(text)||r.get("state").equals("WITHDRAWN"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Já existe relato para esta vaga; não será sobrescrito.");return (UUID)r.get("receipt");}if(db.queryForObject("SELECT count(*) FROM listing_trust_reports WHERE user_id=? AND consent_at>CURRENT_TIMESTAMP-INTERVAL '1 day'",Integer.class,uid)>=5)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS);UUID id=UUID.randomUUID();db.update("INSERT INTO listing_trust_reports(receipt,user_id,listing_id,reason,details) VALUES (?,?,?,?,?)",id,uid,listing,p.reason(),text);return id;});deliver(receipt);return own(email,receipt);}
 public Map<String,Object> own(String email,UUID receipt){long uid=user(email,false);var rows=db.queryForList("SELECT receipt,listing_id,reason,details,state,consent_at FROM listing_trust_reports WHERE receipt=? AND user_id=?",receipt,uid);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);var result=rows.getFirst();if(result.get("state").equals("DELIVERED"))try{result.put("moderation",bridge.convert(bridge.post("/integrations/company-trust/reports/status",new CompanyTrustService.Withdrawal(receipt)),Map.class));}catch(ResponseStatusException unavailable){result.put("moderation",Map.of("status","UNAVAILABLE"));}result.put("notice","Relato privado enviado à moderação; a empresa não recebe sua conta ou contato. Não constitui confirmação de fraude.");return result;}
 public List<Map<String,Object>> list(String email){return db.queryForList("SELECT receipt,listing_id,reason,state,consent_at FROM listing_trust_reports WHERE user_id=? ORDER BY consent_at DESC LIMIT 100",user(email,false));}
 public void withdraw(String email,UUID receipt){tx.executeWithoutResult(status->{long uid=user(email,true);if(db.update("UPDATE listing_trust_reports SET state='WITHDRAWN',details='' WHERE receipt=? AND user_id=?",receipt,uid)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);db.update("INSERT INTO listing_report_erasure(receipt) VALUES (?) ON CONFLICT DO NOTHING",receipt);});}
 private void deliver(UUID receipt){var rows=db.queryForList("SELECT * FROM listing_trust_reports WHERE receipt=? AND state='PENDING'",receipt);if(rows.isEmpty())return;var r=rows.getFirst();try{bridge.post("/integrations/company-trust/reports",new CompanyTrustService.Report(receipt,((Number)r.get("listing_id")).longValue(),trail,r.get("reason").toString(),r.get("details").toString()));db.update("UPDATE listing_trust_reports SET state='DELIVERED',attempts=attempts+1 WHERE receipt=? AND state='PENDING'",receipt);}catch(ResponseStatusException e){boolean permanent=e.getStatusCode().is4xxClientError()&&e.getStatusCode().value()!=429;db.update("UPDATE listing_trust_reports SET state=CASE WHEN ? OR attempts>=9 THEN 'FAILED' ELSE 'PENDING' END,attempts=attempts+1,next_at=CURRENT_TIMESTAMP+make_interval(secs=>LEAST(3600,30*(attempts+1))) WHERE receipt=? AND state='PENDING'",permanent,receipt);}}
 public void pump(){for(UUID receipt:db.queryForList("SELECT receipt FROM listing_trust_reports WHERE state='PENDING' AND next_at<=CURRENT_TIMESTAMP ORDER BY consent_at LIMIT 20",UUID.class))deliver(receipt);for(UUID receipt:db.queryForList("SELECT receipt FROM listing_report_erasure WHERE next_at<=CURRENT_TIMESTAMP LIMIT 20",UUID.class))try{bridge.post("/integrations/company-trust/reports/withdraw",new CompanyTrustService.Withdrawal(receipt));db.update("DELETE FROM listing_report_erasure WHERE receipt=?",receipt);}catch(ResponseStatusException e){db.update("UPDATE listing_report_erasure SET attempts=LEAST(attempts+1,100),next_at=CURRENT_TIMESTAMP+make_interval(secs=>LEAST(3600,30*(attempts+1))) WHERE receipt=?",receipt);}}
 public Map<String,Object> retry(String email,UUID receipt){tx.executeWithoutResult(status->{long uid=user(email,true);var rows=db.queryForList("SELECT state,next_at FROM listing_trust_reports WHERE receipt=? AND user_id=? FOR UPDATE",receipt,uid);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);var r=rows.getFirst();if(!r.get("state").equals("FAILED"))throw new ResponseStatusException(HttpStatus.CONFLICT);if(((java.sql.Timestamp)r.get("next_at")).toInstant().isAfter(java.time.Instant.now()))throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS);db.update("UPDATE listing_trust_reports SET state='PENDING',attempts=0,next_at=CURRENT_TIMESTAMP WHERE receipt=?",receipt);});deliver(receipt);return own(email,receipt);}
}
